(()=>{
let opened=false,busy=false,ready=false,messages=[{role:'assistant',text:'Hi — I’m Guardian AI, powered by Amazon Bedrock Nova Pro. Ask for the nearest pharmacy in this website’s network, or about medicines, symptoms and medicine-related emergencies. I provide general medical information and redirect unrelated topics. Pharmacy inventory is synthetic demo data.'}];
const host=document.createElement('section');host.className='guardian-widget';host.setAttribute('aria-label','Guardian AI assistant');document.body.appendChild(host);
function draw(){host.innerHTML=opened?`<div class="guardian-head"><div class="guardian-orb">✚</div><div><strong>Guardian AI</strong><small>Amazon Bedrock · ${ready?'Configured, access checked on request':'Setup required'}</small></div><button id="guardian-close" aria-label="Minimize Guardian chat">−</button></div><div class="guardian-messages" role="log" aria-live="polite">${messages.map(m=>`<div class="guardian-message ${m.role}">${esc(m.text)}</div>`).join('')}${busy?'<div class="guardian-message assistant">Asking Amazon Bedrock…</div>':''}</div><form id="guardian-widget-form"><label class="sr-chat" for="guardian-widget-input">Ask Guardian AI</label><div class="guardian-input"><input id="guardian-widget-input" maxlength="3000" required placeholder="Ask for a nearby pharmacy or medicine…" ${busy?'disabled':''}><button aria-label="Send message" ${busy?'disabled':''}>→</button></div></form><div class="guardian-status">${ready?'Guardrails on · ≤120 words · Pharmacist approval required':'Live AI unavailable until AWS credentials, region, and model are configured.'}</div>`:`<button id="guardian-open" class="guardian-launch">✚ &nbsp; Ask Guardian AI <span>↗</span></button>`;
host.querySelector('#guardian-open')?.addEventListener('click',()=>{opened=true;draw()});host.querySelector('#guardian-close')?.addEventListener('click',()=>{opened=false;draw()});host.querySelector('#guardian-widget-form')?.addEventListener('submit',send);const log=host.querySelector('.guardian-messages');if(log)log.scrollTop=log.scrollHeight;
}
async function send(e){e.preventDefault();const input=host.querySelector('input');const question=input.value.trim();if(!question||busy)return;messages.push({role:'user',text:question});if(!ready){messages.push({role:'assistant',text:'Bedrock is not connected. Sign in to your AWS workshop and configure the local server’s AWS credentials, region, and model ID. I have not sent this question to a model.'});draw();return}busy=true;draw();try{const r=await fetch('/api/chat',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({message:question,area:finderArea,medicine:finderMedicine,network:facilities,incident:state.brief||state.chatIncident||'',page:location.hash,citywide:state.chatChoice==='citywide',required_volume_l:volume()})});const data=await r.json();if(!r.ok)throw Error(data.error||'Bedrock request failed.');messages.push({role:'assistant',text:data.answer+(data.requestId?'\n\nModel: '+data.model+' · Request: '+data.requestId:'\n\nApplication guardrail · Not sent to Bedrock')});log(data.provider==='aws-bedrock'?'Guardian response validated':'Guardian guardrail applied',data.guardrail||'validated')}catch(e){messages.push({role:'assistant',text:e.message+' No example answer was substituted.'})}finally{busy=false;draw()}}
window.addEventListener('guardian-nearest-pharmacy',()=>{if(busy)return;opened=true;draw();const input=host.querySelector('input');input.value='Which is the nearest powered pharmacy in the website network? Give its distance, driving time, and power details.';send({preventDefault:()=>{}})});
draw();fetch('/api/status').then(r=>r.json()).then(data=>{ready=Boolean(data.configured);draw()}).catch(()=>{});
})();
